@csrf.exempt
def chat_stream():
    message = request.form.get('message', '')
    conversation_id = request.form.get('conversation_id')
    files = request.files.getlist('files')
    user_id = session.get('user_id')
    is_guest = session.get('is_guest', False)
    if not llm_client:
        return jsonify({'error': 'LLM API nem elérhető'}), 503
    conn = get_db_connection()
    cur = conn.cursor()
    if not conversation_id:
        conversation_id = str(uuid.uuid4())
        title = message[:50] if message else 'Új beszélgetés'
        if is_guest:
            cur.execute(
                """INSERT INTO conversations (id, guest_id, title, last_message)
                   VALUES (%s, %s, %s, %s)""",
                (conversation_id, user_id, title, message[:100])
            )
        else:
            cur.execute(
                """INSERT INTO conversations (id, user_id, title, last_message)
                   VALUES (%s, %s, %s, %s)""",
                (conversation_id, user_id, title, message[:100])
            )
        conn.commit()
    cur.execute(
        "INSERT INTO messages (conversation_id, role, content) VALUES (%s, %s, %s)",
        (conversation_id, 'user', message)
    )
    cur.execute(
        "UPDATE conversations SET last_message = %s WHERE id = %s",
        (message[:100], conversation_id)
    )
    conn.commit()
    cur.execute(
        """SELECT role, content FROM messages
           WHERE conversation_id = %s
           ORDER BY created_at DESC LIMIT 20""",
        (conversation_id,)
    )
    history_rows = cur.fetchall()
    cur.close()
    conn.close()
    file_contents = []
    allowed_extensions = {'txt', 'md', 'json', 'csv', 'xml', 'html', 'css', 'js', 'py'}
    for f in files:
        ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else ''
        if ext in allowed_extensions:
            try:
                file_data = read_file_chunked(f, MAX_FILE_SIZE)
                content = file_data.decode('utf-8', errors='ignore')
                sanitized = sanitize_file_content(content)
                file_contents.append("[Fájl: " + f.filename + "]\n" + sanitized)
            except ValueError:
                file_contents.append("[Fájl: " + f.filename + "] - Túl nagy fájl")
            except Exception:
                pass
    full_message = message
    if file_contents:
        full_message = message + "\n\n" + "\n\n".join(file_contents)
    tools = [
        {
            "type": "function",
            "function": {
                "name": "web_search",
                "description": "Keresés a weben aktuális információkért. Mindig használd friss hírek, árak, események esetén.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "query": {
                            "type": "string",
                            "description": "A keresési lekérdezés"
                        }
                    },
                    "required": ["query"]
                }
            }
        }
    ] if exa_client else []

    def generate():
        yield "data: " + json.dumps({
            'type': 'start',
            'conversation_id': conversation_id
        }) + "\n\n"
        messages = [{"role": "system", "content": SYSTEM_PROMPT}]
        history = list(reversed(history_rows))
        for msg in history:
            messages.append({
                "role": msg['role'],
                "content": msg['content']
            })
        messages.append({"role": "user", "content": full_message})
        full_response = ""
        try:
            while True:
                response = llm_client.chat.completions.create(
                    model=llm_model,
                    messages=messages,
                    max_completion_tokens=32768,
                    temperature=0.14,
                    top_p=1,
                    tools=tools or None,
                    tool_choice="auto" if tools else "none"
                )
                choice = response.choices[0]
                message = choice.message
                if message.content:
                    full_response += message.content
                    yield "data: " + json.dumps({
                        'type': 'token',
                        'content': message.content
                    }) + "\n\n"
                if message.tool_calls:
                    messages.append({
                        "role": "assistant",
                        "content": message.content or "",
                        "tool_calls": [tc.dict() for tc in message.tool_calls]
                    })
                    for tool_call in message.tool_calls:
                        if tool_call.function.name == "web_search":
                            yield "data: " + json.dumps({
                                'type': 'thinking',
                                'content': f"Keresés indítása: {json.loads(tool_call.function.arguments)['query']}"
                            }) + "\n\n"
                            args = json.loads(tool_call.function.arguments)
                            query = args.get("query", "")
                            result_text = "Nincs találat."
                            if query:
                                try:
                                    search_results = exa_client.search(query, num_results=100)
                                    result_text = "Keresési eredmények:\n\n"
                                    for r in search_results.results[:30]:
                                        snippet = getattr(r, 'snippet', '') or getattr(r, 'text', '') or ''
                                        result_text += f"Cím: {r.title}\nLink: {r.url}\nKivonat: {snippet[:500]}\n\n"
                                except Exception as e:
                                    result_text = f"Keresési hiba: {str(e)}"
                            messages.append({
                                "role": "tool",
                                "tool_call_id": tool_call.id,
                                "name": tool_call.function.name,
                                "content": result_text
                            })
                else:
                    break
            conn2 = get_db_connection()
            cur2 = conn2.cursor()
            cur2.execute(
                "INSERT INTO messages (conversation_id, role, content) VALUES (%s, %s, %s)",
                (conversation_id, 'assistant', full_response)
            )
            conn2.commit()
            cur2.close()
            conn2.close()
            yield "data: " + json.dumps({'type': 'done'}) + "\n\n"
        except Exception as e:
            error_msg = str(e) if str(e) else 'Ismeretlen hiba'
            yield "data: " + json.dumps({
                'type': 'error',
                'content': 'Hiba történt: ' + error_msg
            }) + "\n\n"
            yield "data: " + json.dumps({'type': 'done'}) + "\n\n"

    return Response(generate(), mimetype='text/event-stream', headers={
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
        'X-Accel-Buffering': 'no'
    })

