@app.route('/api/image/generate/stream', methods=['POST'])
@csrf.exempt
def generate_image_stream():
    data = request.get_json()
    if not data:
        return jsonify({'success': False, 'error': 'Érvénytelen kérés'}), 400
    prompt = data.get('prompt', '').strip()
    if not prompt:
        return jsonify({'success': False, 'error': 'Prompt megadása kötelező'}), 400
    user_id = session.get('user_id')
    is_guest = session.get('is_guest', False)

    def generate():
        yield "data: " + json.dumps({'type': 'start', 'message': 'Kép generálása...'}) + "\n\n"
        client = get_gemini_client()
        if not client:
            yield "data: " + json.dumps({'type': 'error', 'message': 'Gemini API kulcs nincs beállítva'}) + "\n\n"
            return
        model = "gemini-3-pro-image-preview"
        contents = [
            types.Content(
                role="user",
                parts=[
                    types.Part.from_text(text=prompt),
                ],
            ),
        ]
        generate_content_config = types.GenerateContentConfig(
            response_modalities=[
                "IMAGE",
                "TEXT",
            ],
        )
        try:
            for chunk in client.models.generate_content_stream(
                model=model,
                contents=contents,
                config=generate_content_config,
            ):
                if not chunk.candidates or not chunk.candidates[0].content or not chunk.candidates[0].content.parts:
                    continue
                for part in chunk.candidates[0].content.parts:
                    if part.inline_data and part.inline_data.data:
                        image_data = part.inline_data.data
                        if is_guest:
                            file_path, image_id = save_generated_image(image_data, prompt, guest_id=user_id)
                        else:
                            file_path, image_id = save_generated_image(image_data, prompt, user_id=user_id)
                        yield "data: " + json.dumps({
                            'type': 'image',
                            'image_id': image_id,
                            'image_url': f'/api/image/{image_id}'
                        }) + "\n\n"
                    elif part.text:
                        yield "data: " + json.dumps({
                            'type': 'text',
                            'content': part.text
                        }) + "\n\n"
            yield "data: " + json.dumps({'type': 'done'}) + "\n\n"
        except Exception as e:
            yield "data: " + json.dumps({'type': 'error', 'message': str(e)}) + "\n\n"

    return Response(generate(), mimetype='text/event-stream', headers={
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
        'X-Accel-Buffering': 'no'
    })

