        cur.execute(
            """SELECT id, prompt, created_at FROM generated_images
               WHERE guest_id = %s ORDER BY created_at DESC LIMIT 50""",
            (user_id,)
        )
    else:
        cur.execute(
            """SELECT id, prompt, created_at FROM generated_images
               WHERE user_id = %s ORDER BY created_at DESC LIMIT 50""",
            (user_id,)
        )
    rows = cur.fetchall()
    cur.close()
    conn.close()
    images = []
    for row in rows:
        images.append({
            'id': str(row['id']),
            'prompt': row['prompt'],
            'url': f"/api/image/{row['id']}",
            'created_at': row['created_at'].isoformat() if row['created_at'] else None
        })
    return jsonify({'images': images})

